import { Link, useLocation, useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import { useState } from "react";
import { useAuth } from "../context/AuthContext";
import "../App.css";

function Navbar() {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout, isAuthenticated, isAdmin } = useAuth();
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  const isActive = (path) => location.pathname === path;

  const handleLogout = () => {
    if (window.confirm("로그아웃 하시겠습니까?")) {
      logout();
      navigate("/");
      alert("로그아웃 되었습니다.");
      setShowProfileMenu(false);
    }
  };

  return (
    <motion.nav
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        background: "#fff", // 🔁 화이트 배경
        padding: "20px 80px",
        boxShadow: "0 2px 20px rgba(0, 0, 0, 0.1)",
        position: "sticky",
        top: 0,
        zIndex: 1000,
        borderBottom: "1px solid rgba(0, 0, 0, 0.05)",
      }}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
    >
      {/* Logo */}
      <Link to="/" style={{ textDecoration: "none" }}>
        <motion.div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <div
            style={{
              width: "40px",
              height: "40px",
              background: "linear-gradient(155deg, #ff4d00 0%, #ff8c00 100%)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "8px",
              boxShadow: "0 4px 12px rgba(255, 107, 53, 0.3)",
            }}
          >
            <span style={{ color: "#fff", fontSize: "22px", fontWeight: "800" }}>A</span>
          </div>
          <span style={{ fontSize: "20px", fontWeight: "700", color: "#111" }}>ASSEMBLE</span>
        </motion.div>
      </Link>

      {/* Navigation Menu */}
      <ul
        style={{
          display: "flex",
          gap: "50px",
          listStyle: "none",
          margin: 0,
          padding: 0,
          alignItems: "center",
        }}
      >
        {[
          { path: "/projects", label: "My Project" },
          { path: "/resources", label: "Resources" },
          { path: "/library", label: "Library" },
          { path: "/about", label: "About Us" },
          ...(isAdmin ? [{ path: "/admin", label: "Admin" }] : []),
        ].map((item) => (
          <li key={item.path}>
            <Link to={item.path} style={{ textDecoration: "none" }}>
              <motion.div
                style={{
                  fontSize: "15px",
                  fontWeight: isActive(item.path) ? 600 : 500,
                  color: isActive(item.path) ? "#ff4d00" : "#222", // 🔁 블랙계열 텍스트
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  opacity: isActive(item.path) ? 1 : 0.7,
                  position: "relative",
                  paddingBottom: isActive(item.path) ? "4px" : "0",
                  borderBottom: isActive(item.path)
                    ? "2px solid #ff6b35"
                    : "2px solid transparent",
                }}
                whileHover={{ opacity: 1, color: "#000" }}
              >
                {item.label}
              </motion.div>
            </Link>
          </li>
        ))}
      </ul>

      {/* Login/Logout Section */}
      {isAuthenticated ? (
        <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
          <span
            style={{
              color: "#222",
              fontSize: "15px",
              fontWeight: "500",
              opacity: 0.9,
            }}
          >
            {user?.username}님
          </span>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              style={{
                background: "rgba(0, 0, 0, 0.05)",
                border: "1px solid rgba(0, 0, 0, 0.1)",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "15px",
                color: "#111",
                fontWeight: "500",
                padding: "10px 18px",
                borderRadius: "8px",
                transition: "all 0.3s ease",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = "rgba(0,0,0,0.08)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = "rgba(0,0,0,0.05)";
              }}
            >
              <span style={{ fontSize: "15px" }}>🔑</span>
              Profile
            </button>

            {showProfileMenu && (
              <div
                style={{
                  position: "absolute",
                  top: "calc(100% + 7px)",
                  right: 0,
                  background: "#fff",
                  border: "1px solid rgba(0, 0, 0, 0.1)",
                  borderRadius: "7px",
                  padding: "7px",
                  boxShadow: "0 8px 24px rgba(0,0,0,0.1)",
                  minWidth: "117px",
                }}
              >
                <button
                  onClick={handleLogout}
                  style={{
                    width: "100%",
                    padding: "10px 14px",
                    background: "#ff6b35",
                    border: "none",
                    textAlign: "center",
                    cursor: "pointer",
                    fontSize: "15px",
                    color: "#fff",
                    borderRadius: "8px",
                    fontWeight: "600",
                    transition: "all 0.2s ease",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = "#ff4d00";
                    e.currentTarget.style.transform = "translateY(-2px)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = "#ff6b35";
                    e.currentTarget.style.transform = "translateY(0)";
                  }}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      ) : (
        <Link to="/login" style={{ textDecoration: "none" }}>
          <motion.button
            style={{
              padding: "10px 28px",
              border: "none",
              borderRadius: "12px",
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              color: "#fff",
              fontSize: "15px",
              fontWeight: 700,
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(255, 107, 53, 0.3)",
              transition: "all 0.3s ease",
            }}
            whileHover={{
              scale: 1.05,
              boxShadow: "0 6px 20px rgba(255, 107, 53, 0.4)",
            }}
            whileTap={{ scale: 0.95 }}
          >
            Login
          </motion.button>
        </Link>
      )}
    </motion.nav>
  );
}

export default Navbar;
